    add hl, de
    ld b, (hl)
    ld a, (music_active)
    or a
    jr z, ensure_music_for_world_id_play_track
    ld a, (music_track_index)
    cp c
    jr nz, ensure_music_for_world_id_play_track
    ld a, (music_loop)
    and 1
    cp b
    ret z
